1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"sort"
10		"strings"
11	)
12	
13	// Reason constants for clusters that cannot enter a release plan.
14	const (
15		ReasonDisabled          = "集群已停用"
16		ReasonExcludeMatched    = "命中排除条件"
17		ReasonIncludeNotMatched = "未命中包含条件"
18	)
19	
20	// LabelCondition is a set of exact key-value matches; all must match.
21	type LabelCondition map[string]string
22	
23	// Cluster is a candidate target for a release.
24	type Cluster struct {
25		ID       string
26		Disabled bool
27		Tags     map[string]string
28	}
29	
30	// ReleasePlanInput describes an application release to plan offline.
31	type ReleasePlanInput struct {
32		App       string
33		Revision  string
34		Image     string
35		BatchSize int
36		Clusters  []Cluster
37		Include   []LabelCondition
38		Exclude   []LabelCondition
39		// SpreadBy, when non-empty, names a cluster tag whose value identifies a
40		// fault domain; each batch then contains at most one cluster per domain.
41		SpreadBy string
42	}
43	
44	// AppInfo identifies the application being released.
45	type AppInfo struct {
46		Name     string `json:"name"`
47		Revision string `json:"revision"`
48		Image    string `json:"image"`
49	}
50	
51	// Batch is a sequentially numbered group of cluster IDs.
52	type Batch struct {
53		Index    int      `json:"index"`
54		Clusters []string `json:"clusters"`
55	}
56	
57	// ExcludedCluster explains why a cluster is not in the plan.
58	type ExcludedCluster struct {
59		ID     string `json:"id"`
60		Reason string `json:"reason"`
61	}
62	
63	// ReleasePlan is the deterministic offline release plan.
64	type ReleasePlan struct {
65		App      AppInfo           `json:"app"`
66		Batches  []Batch           `json:"batches"`
67		Excluded []ExcludedCluster `json:"excluded"`
68	}
69	
70	// ParseReleaseInput reads a release plan document and validates its fields.
71	// Every JSON object in the document — including unknown fields and their
72	// nested objects — must have distinct member names; a name appearing twice
73	// (even with the same value, or via equivalent Unicode escapes) is rejected
74	// before any business validation runs.
75	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
76		if err := checkDuplicateMembers(data); err != nil {
77			return ReleasePlanInput{}, err
78		}
79		dec := json.NewDecoder(bytes.NewReader(data))
80		dec.UseNumber()
81		var doc map[string]any
82		if err := dec.Decode(&doc); err != nil {
83			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
84		}
85		if dec.More() {
86			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
87		}
88		return buildReleaseInput(doc)
89	}
90	
91	// duplicateMemberError reports a JSON object whose member name appears more
92	// than once. Path is a JSONPath-style location: "$" for the document root,
93	// "$.clusters[1]" for a cluster, "$.clusters[0].tags" for a tag object,
94	// "$.include[2]" / "$.exclude[1]" for a condition, and "$.foo.bar[0]" for
95	// objects nested inside unknown fields.
96	type duplicateMemberError struct {
97		field string
98		path  string
99	}
100	
101	func (e *duplicateMemberError) Error() string {
102		return fmt.Sprintf("JSON 对象存在重复成员: 字段 %q 重复出现于 %s", e.field, e.path)
103	}
104	
105	// checkDuplicateMembers walks every JSON object in data and rejects objects
106	// with duplicate member names. Names are compared after JSON decoding, so
107	// "env" and "env" are the same name while "env" and "ENV", or
108	// " env" and "env", are different. The first duplicate encountered in file
109	// order is reported: the walk is depth-first in document order, so the
110	// second occurrence that appears earliest wins, regardless of value type.
111	func checkDuplicateMembers(data []byte) error {
112		dec := json.NewDecoder(bytes.NewReader(data))
113		if err := walkJSONValue(dec, "$"); err != nil {
114			return err
115		}
116		if _, err := dec.Token(); err != io.EOF {
117			if err == nil {
118				return errors.New("JSON 格式错误: 文档包含多余内容")
119			}
120			return fmt.Errorf("JSON 格式错误: %w", err)
121		}
122		return nil
123	}
124	
125	// walkJSONValue reads one complete JSON value whose first token has not been
126	// consumed yet.
127	func walkJSONValue(dec *json.Decoder, path string) error {
128		tok, err := dec.Token()
129		if err != nil {
130			if err == io.EOF {
131				return errors.New("JSON 格式错误: 文档为空")
132			}
133			return fmt.Errorf("JSON 格式错误: %w", err)
134		}
135		return walkJSONValueToken(dec, path, tok)
136	}
137	
138	// walkJSONValueToken reads the remainder of a value given its first token.
139	func walkJSONValueToken(dec *json.Decoder, path string, tok json.Token) error {
140		if d, ok := tok.(json.Delim); ok {
141			switch d {
142			case '{':
143				return walkJSONObject(dec, path)
144			case '[':
145				return walkJSONArray(dec, path)
146			default:
147				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
148			}
149		}
150		return nil // scalar value (string, number, bool, null)
151	}
152	
153	func walkJSONObject(dec *json.Decoder, path string) error {
154		seen := make(map[string]struct{})
155		for {
156			tok, err := dec.Token()
157			if err != nil {
158				if err == io.EOF {
159					return errors.New("JSON 格式错误: 对象未闭合")
160				}
161				return fmt.Errorf("JSON 格式错误: %w", err)
162			}
163			if d, ok := tok.(json.Delim); ok {
164				if d == '}' {
165					return nil
166				}
167				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
168			}
169			key, ok := tok.(string)
170			if !ok {
171				return errors.New("JSON 格式错误: 对象成员名必须是字符串")
172			}
173			if _, dup := seen[key]; dup {
174				return &duplicateMemberError{field: key, path: path}
175			}
176			seen[key] = struct{}{}
177			vtok, err := dec.Token()
178			if err != nil {
179				if err == io.EOF {
180					return errors.New("JSON 格式错误: 缺少成员值")
181				}
182				return fmt.Errorf("JSON 格式错误: %w", err)
183			}
184			if err := walkJSONValueToken(dec, path+"."+key, vtok); err != nil {
185				return err
186			}
187		}
188	}
189	
190	func walkJSONArray(dec *json.Decoder, path string) error {
191		for i := 0; ; i++ {
192			tok, err := dec.Token()
193			if err != nil {
194				if err == io.EOF {
195					return errors.New("JSON 格式错误: 数组未闭合")
196				}
197				return fmt.Errorf("JSON 格式错误: %w", err)
198			}
199			if d, ok := tok.(json.Delim); ok && d == ']' {
200				return nil
201			}
202			if err := walkJSONValueToken(dec, fmt.Sprintf("%s[%d]", path, i), tok); err != nil {
203				return err
204			}
205		}
206	}
207	
208	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
209		app, err := requiredString(doc, "app")
210		if err != nil {
211			return ReleasePlanInput{}, err
212		}
213		revision, err := requiredString(doc, "revision")
214		if err != nil {
215			return ReleasePlanInput{}, err
216		}
217		image, err := requiredString(doc, "image")
218		if err != nil {
219			return ReleasePlanInput{}, err
220		}
221		batchSize, err := positiveInt(doc, "batchSize")
222		if err != nil {
223			return ReleasePlanInput{}, err
224		}
225		spreadBy, err := optionalSpreadBy(doc)
226		if err != nil {
227			return ReleasePlanInput{}, err
228		}
229		clusters, err := parseClusters(doc["clusters"])
230		if err != nil {
231			return ReleasePlanInput{}, err
232		}
233		include, err := parseConditions(doc["include"], "include")
234		if err != nil {
235			return ReleasePlanInput{}, err
236		}
237		exclude, err := parseConditions(doc["exclude"], "exclude")
238		if err != nil {
239			return ReleasePlanInput{}, err
240		}
241	
242		return ReleasePlanInput{
243			App:       app,
244			Revision:  revision,
245			Image:     image,
246			BatchSize: batchSize,
247			Clusters:  clusters,
248			Include:   include,
249			Exclude:   exclude,
250			SpreadBy:  spreadBy,
251		}, nil
252	}
253	
254	// optionalSpreadBy reads the optional "spreadBy" field: absent or an empty
255	// string disables fault-domain spreading; a non-string value or a string of
256	// only whitespace is rejected. The tag key is used exactly as written.
257	func optionalSpreadBy(doc map[string]any) (string, error) {
258		v, ok := doc["spreadBy"]
259		if !ok {
260			return "", nil
261		}
262		s, ok := v.(string)
263		if !ok {
264			return "", fmt.Errorf("字段 %q 必须是字符串", "spreadBy")
265		}
266		if err := checkSpreadBy(s); err != nil {
267			return "", err
268		}
269		return s, nil
270	}
271	
272	// checkSpreadBy rejects a spreadBy value that is neither empty nor a usable
273	// tag key: a string of only whitespace can never match a valid tag key.
274	func checkSpreadBy(s string) error {
275		if s != "" && strings.TrimSpace(s) == "" {
276			return fmt.Errorf("字段 %q 不能只含空白", "spreadBy")
277		}
278		return nil
279	}
280	
281	// ValidateReleaseInput checks that a release configuration is well-formed:
282	// app/revision/image are non-empty, batchSize is a positive integer, spreadBy
283	// is empty or a usable tag key (not whitespace-only), cluster
284	// IDs are unique across every candidate (including disabled and filtered-out
285	// clusters), and tag/condition keys are non-empty. Errors name the field and
286	// the position in its list; within a cluster the ID is checked before its
287	// tags, and tag keys are examined in ascending order so repeated calls report
288	// the same error. The input is never mutated. MakeReleasePlan calls this
289	// automatically; library callers may use it to validate without planning.
290	func ValidateReleaseInput(in ReleasePlanInput) error {
291		if strings.TrimSpace(in.App) == "" {
292			return errors.New(`字段 "app" 不能为空或只含空白`)
293		}
294		if strings.TrimSpace(in.Revision) == "" {
295			return errors.New(`字段 "revision" 不能为空或只含空白`)
296		}
297		if strings.TrimSpace(in.Image) == "" {
298			return errors.New(`字段 "image" 不能为空或只含空白`)
299		}
300		if in.BatchSize <= 0 {
301			return errors.New(`字段 "batchSize" 必须是正整数`)
302		}
303		if err := checkSpreadBy(in.SpreadBy); err != nil {
304			return err
305		}
306		seen := make(map[string]struct{}, len(in.Clusters))
307		for i, c := range in.Clusters {
308			if strings.TrimSpace(c.ID) == "" {
309				return fmt.Errorf("clusters[%d]: 字段 %q 不能为空或只含空白", i, "id")
310			}
311			if _, dup := seen[c.ID]; dup {
312				return fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, c.ID)
313			}
314			seen[c.ID] = struct{}{}
315			if err := validateTagKeys(i, c.Tags); err != nil {
316				return err
317			}
318		}
319		if err := validateConditionKeys("include", in.Include); err != nil {
320			return err
321		}
322		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
323			return err
324		}
325		return nil
326	}
327	
328	// validateTagKeys checks tag keys in ascending order for deterministic errors.
329	func validateTagKeys(clusterIndex int, tags map[string]string) error {
330		keys := make([]string, 0, len(tags))
331		for k := range tags {
332			keys = append(keys, k)
333		}
334		sort.Strings(keys)
335		for _, k := range keys {
336			if k == "" {
337				return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
338			}
339		}
340		return nil
341	}
342	
343	// validateConditionKeys checks that every condition is non-empty and has only
344	// non-empty keys; conditions are visited in original order and keys in
345	// ascending order for deterministic errors.
346	func validateConditionKeys(field string, conds []LabelCondition) error {
347		for i, cond := range conds {
348			if len(cond) == 0 {
349				return fmt.Errorf("%s[%d] 不能为空条件对象", field, i)
350			}
351			keys := make([]string, 0, len(cond))
352			for k := range cond {
353				keys = append(keys, k)
354			}
355			sort.Strings(keys)
356			for _, k := range keys {
357				if k == "" {
358					return fmt.Errorf("%s[%d] 的标签键不能为空", field, i)
359				}
360			}
361		}
362		return nil
363	}
364	
365	func requiredString(doc map[string]any, field string) (string, error) {
366		v, ok := doc[field]
367		if !ok {
368			return "", fmt.Errorf("缺少必需字段 %q", field)
369		}
370		s, ok := v.(string)
371		if !ok {
372			return "", fmt.Errorf("字段 %q 必须是字符串", field)
373		}
374		if strings.TrimSpace(s) == "" {
375			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
376		}
377		return s, nil
378	}
379	
380	func positiveInt(doc map[string]any, field string) (int, error) {
381		v, ok := doc[field]
382		if !ok {
383			return 0, fmt.Errorf("缺少必需字段 %q", field)
384		}
385		n, ok := v.(json.Number)
386		if !ok {
387			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
388		}
389		i, err := n.Int64()
390		if err != nil || i <= 0 {
391			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
392		}
393		return int(i), nil
394	}
395	
396	func parseClusters(v any) ([]Cluster, error) {
397		if v == nil {
398			return nil, errors.New("缺少必需字段 \"clusters\"")
399		}
400		raw, ok := v.([]any)
401		if !ok {
402			return nil, errors.New("字段 \"clusters\" 必须是数组")
403		}
404		clusters := make([]Cluster, 0, len(raw))
405		seen := make(map[string]bool)
406		for i, item := range raw {
407			obj, ok := item.(map[string]any)
408			if !ok {
409				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
410			}
411			id, err := requiredString(obj, "id")
412			if err != nil {
413				return nil, fmt.Errorf("clusters[%d]: %w", i, err)
414			}
415			if seen[id] {
416				return nil, fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, id)
417			}
418			seen[id] = true
419	
420			disabled := false
421			if dv, present := obj["disabled"]; present {
422				b, ok := dv.(bool)
423				if !ok {
424					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
425				}
426				disabled = b
427			}
428	
429			tags := map[string]string{}
430			if tv, present := obj["tags"]; present {
431				tm, ok := tv.(map[string]any)
432				if !ok {
433					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
434				}
435				keys := make([]string, 0, len(tm))
436				for k := range tm {
437					keys = append(keys, k)
438				}
439				sort.Strings(keys)
440				for _, k := range keys {
441					if k == "" {
442						return nil, fmt.Errorf("集群 %q 的标签键不能为空", id)
443					}
444					sv, ok := tm[k].(string)
445					if !ok {
446						return nil, fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k)
447					}
448					tags[k] = sv
449				}
450			}
451	
452			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
453		}
454		return clusters, nil
455	}
456	
457	func parseConditions(v any, field string) ([]LabelCondition, error) {
458		if v == nil {
459			return []LabelCondition{}, nil
460		}
461		raw, ok := v.([]any)
462		if !ok {
463			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
464		}
465		conds := make([]LabelCondition, 0, len(raw))
466		for i, item := range raw {
467			obj, ok := item.(map[string]any)
468			if !ok {
469				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
470			}
471			if len(obj) == 0 {
472				return nil, fmt.Errorf("%s[%d] 不能为空条件对象", field, i)
473			}
474			cond := LabelCondition{}
475			keys := make([]string, 0, len(obj))
476			for k := range obj {
477				keys = append(keys, k)
478			}
479			sort.Strings(keys)
480			for _, k := range keys {
481				if k == "" {
482					return nil, fmt.Errorf("%s[%d] 的标签键不能为空", field, i)
483				}
484				sv, ok := obj[k].(string)
485				if !ok {
486					return nil, fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k)
487				}
488				cond[k] = sv
489			}
490			conds = append(conds, cond)
491		}
492		return conds, nil
493	}
494	
495	// MakeReleasePlan selects available clusters, orders them by ID, and splits
496	// them into batches. When SpreadBy names a tag, each batch holds at most one
497	// cluster per value of that tag (its fault domain) and every selected cluster
498	// must carry the tag. It validates the input first and never mutates it.
499	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
500		if err := ValidateReleaseInput(in); err != nil {
501			return ReleasePlan{}, err
502		}
503		if len(in.Clusters) == 0 {
504			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
505		}
506	
507		selected := []string{}
508		excluded := []ExcludedCluster{}
509		for _, c := range in.Clusters {
510			switch {
511			case c.Disabled:
512				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
513			case matchesAny(c.Tags, in.Exclude):
514				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
515			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
516				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
517			default:
518				selected = append(selected, c.ID)
519			}
520		}
521	
522		sort.Strings(selected)
523		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
524	
525		if len(selected) == 0 {
526			var b strings.Builder
527			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
528			for _, e := range excluded {
529				b.WriteString("\n  ")
530				b.WriteString(e.ID)
531				b.WriteString("：")
532				b.WriteString(e.Reason)
533			}
534			return ReleasePlan{}, errors.New(b.String())
535		}
536	
537		var batches []Batch
538		if in.SpreadBy == "" {
539			batches = chunkBatches(selected, in.BatchSize)
540		} else {
541			domains, err := faultDomains(in.Clusters, selected, in.SpreadBy)
542			if err != nil {
543				return ReleasePlan{}, err
544			}
545			batches = spreadBatches(selected, domains, in.BatchSize)
546		}
547	
548		return ReleasePlan{
549			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
550			Batches:  batches,
551			Excluded: excluded,
552		}, nil
553	}
554	
555	// chunkBatches splits the ascending IDs into batches of at most batchSize.
556	func chunkBatches(selected []string, batchSize int) []Batch {
557		batches := []Batch{}
558		for i := 0; i < len(selected); i += batchSize {
559			end := i + batchSize
560			if end > len(selected) {
561				end = len(selected)
562			}
563			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: selected[i:end]})
564		}
565		return batches
566	}
567	
568	// faultDomains maps every selected cluster ID to the exact value of its
569	// spreadBy tag. A selected cluster missing the tag fails the whole plan;
570	// selected is ascending, so the smallest such ID is reported. An empty
571	// string tag value is a valid fault domain, distinct from a missing tag.
572	func faultDomains(clusters []Cluster, selected []string, spreadBy string) (map[string]string, error) {
573		tagsByID := make(map[string]map[string]string, len(clusters))
574		for _, c := range clusters {
575			tagsByID[c.ID] = c.Tags
576		}
577		domains := make(map[string]string, len(selected))
578		for _, id := range selected {
579			v, ok := tagsByID[id][spreadBy]
580			if !ok {
581				return nil, fmt.Errorf("集群 %q 缺少故障域标签 %q", id, spreadBy)
582			}
583			domains[id] = v
584		}
585		return domains, nil
586	}
587	
588	// spreadBatches packs the ascending IDs into batches of at most batchSize
589	// with at most one cluster per fault domain in each batch. Each batch takes
590	// the smallest still-unscheduled IDs whose domains do not conflict with the
591	// batch; conflicting clusters are deferred to later batches, so a batch may
592	// be short only when no non-conflicting cluster remains. Every ID appears in
593	// exactly one batch and IDs stay ascending within a batch.
594	func spreadBatches(selected []string, domains map[string]string, batchSize int) []Batch {
595		remaining := append([]string(nil), selected...)
596		batches := []Batch{}
597		for len(remaining) > 0 {
598			used := make(map[string]struct{}, batchSize)
599			batch := []string{}
600			deferred := []string{}
601			for _, id := range remaining {
602				d := domains[id]
603				if _, conflict := used[d]; len(batch) < batchSize && !conflict {
604					used[d] = struct{}{}
605					batch = append(batch, id)
606				} else {
607					deferred = append(deferred, id)
608				}
609			}
610			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: batch})
611			remaining = deferred
612		}
613		return batches
614	}
615	
616	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
617		for _, cond := range conditions {
618			if matchesAll(tags, cond) {
619				return true
620			}
621		}
622		return false
623	}
624	
625	func matchesAll(tags map[string]string, cond LabelCondition) bool {
626		for k, v := range cond {
627			tv, ok := tags[k]
628			if !ok || tv != v {
629				return false
630			}
631		}
632		return true
633	}
