1	package darksafe
2	
3	import (
4		"os"
5		"os/exec"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// parseDupErr parses data and returns the error; it fails the test if no
12	// error is returned.
13	func parseDupErr(t *testing.T, data string) error {
14		t.Helper()
15		_, err := ParseReleaseInput([]byte(data))
16		if err == nil {
17			t.Fatalf("expected duplicate-member error for %s", data)
18		}
19		return err
20	}
21	
22	func TestParse_DuplicateMemberRejectedEverywhere(t *testing.T) {
23		base := `"app":"a","revision":"r","image":"i","batchSize":1`
24		cases := []struct {
25			name      string
26			body      string // JSON body without outer braces
27			wantField string
28			wantPath  string
29		}{
30			{
31				name:      "top-level app",
32				body:      `"app":"a","app":"b","revision":"r","image":"i","batchSize":1,"clusters":[]`,
33				wantField: "app",
34				wantPath:  "$",
35			},
36			{
37				name:      "top-level batchSize",
38				body:      `"app":"a","revision":"r","image":"i","batchSize":1,"batchSize":2,"clusters":[]`,
39				wantField: "batchSize",
40				wantPath:  "$",
41			},
42			{
43				name:      "cluster disabled",
44				body:      base + `,"clusters":[{"id":"x","disabled":true,"disabled":false}]`,
45				wantField: "disabled",
46				wantPath:  "$.clusters[0]",
47			},
48			{
49				name:      "cluster id",
50				body:      base + `,"clusters":[{"id":"x","id":"y"}]`,
51				wantField: "id",
52				wantPath:  "$.clusters[0]",
53			},
54			{
55				name:      "second cluster",
56				body:      base + `,"clusters":[{"id":"a"},{"id":"b","disabled":false,"disabled":true}]`,
57				wantField: "disabled",
58				wantPath:  "$.clusters[1]",
59			},
60			{
61				name:      "tags",
62				body:      base + `,"clusters":[{"id":"x","tags":{"env":"prod","env":"dev"}}]`,
63				wantField: "env",
64				wantPath:  "$.clusters[0].tags",
65			},
66			{
67				name:      "include condition",
68				body:      base + `,"clusters":[],"include":[{"env":"prod","env":"dev"}]`,
69				wantField: "env",
70				wantPath:  "$.include[0]",
71			},
72			{
73				name:      "exclude condition",
74				body:      base + `,"clusters":[],"exclude":[{"region":"us","region":"eu"}]`,
75				wantField: "region",
76				wantPath:  "$.exclude[0]",
77			},
78			{
79				name:      "second include condition",
80				body:      base + `,"clusters":[],"include":[{"env":"prod"},{"env":"dev","env":"staging"}]`,
81				wantField: "env",
82				wantPath:  "$.include[1]",
83			},
84			{
85				name:      "unknown field nested object",
86				body:      base + `,"clusters":[],"meta":{"x":1,"x":2}`,
87				wantField: "x",
88				wantPath:  "$.meta",
89			},
90			{
91				name:      "unknown field array of objects",
92				body:      base + `,"clusters":[],"items":[{"y":1,"y":2}]`,
93				wantField: "y",
94				wantPath:  "$.items[0]",
95			},
96			{
97				name:      "unknown field deep nesting",
98				body:      base + `,"clusters":[],"a":{"b":{"c":[{"z":1,"z":2}]}}`,
99				wantField: "z",
100				wantPath:  "$.a.b.c[0]",
101			},
102		}
103		for _, tc := range cases {
104			t.Run(tc.name, func(t *testing.T) {
105				err := parseDupErr(t, "{"+tc.body+"}")
106				msg := err.Error()
107				if !strings.Contains(msg, tc.wantField) {
108					t.Fatalf("error %q does not name field %q", msg, tc.wantField)
109				}
110				if !strings.Contains(msg, tc.wantPath) {
111					t.Fatalf("error %q does not contain path %q", msg, tc.wantPath)
112				}
113			})
114		}
115	}
116	
117	func TestParse_DuplicateRejectedRegardlessOfValues(t *testing.T) {
118		base := `"app":"a","revision":"r","image":"i","batchSize":1`
119		// Same value twice must still be rejected.
120		for _, val := range []string{`true`, `false`, `null`, `1`, `1.5`, `"str"`, `[1,2]`, `{"k":"v"}`} {
121			t.Run("same value "+val, func(t *testing.T) {
122				body := `{"id":"x","tags":{"env":` + val + `,"env":` + val + `}}`
123				err := parseDupErr(t, `{`+base+`,"clusters":[`+body+`]}`)
124				if !strings.Contains(err.Error(), "env") {
125					t.Fatalf("expected field name in %q", err)
126				}
127			})
128		}
129		// Different value types on either side must be rejected.
130		pairs := [][2]string{
131			{`1`, `true`},
132			{`"a"`, `null`},
133			{`[]`, `{}`},
134			{`false`, `"false"`},
135		}
136		for _, p := range pairs {
137			t.Run("mixed "+p[0]+" "+p[1], func(t *testing.T) {
138				body := `{"id":"x","tags":{"env":` + p[0] + `,"env":` + p[1] + `}}`
139				err := parseDupErr(t, `{`+base+`,"clusters":[`+body+`]}`)
140				if !strings.Contains(err.Error(), "env") {
141					t.Fatalf("expected field name in %q", err)
142				}
143			})
144		}
145	}
146	
147	func TestParse_DuplicateNamesComparedAfterDecoding(t *testing.T) {
148		base := `"app":"a","revision":"r","image":"i","batchSize":1`
149		// Equivalent Unicode escape spellings are the same name.
150		body := `{"id":"x","tags":{"env":"prod","env":"dev"}}`
151		err := parseDupErr(t, `{`+base+`,"clusters":[`+body+`]}`)
152		if !strings.Contains(err.Error(), `"env"`) {
153			t.Fatalf("expected decoded field name \"env\" in %q", err)
154		}
155	
156		// Case differences are different names.
157		valid := `{` + base + `,"clusters":[{"id":"x","tags":{"env":"prod","ENV":"dev"}}]}`
158		if _, err := ParseReleaseInput([]byte(valid)); err != nil {
159			t.Fatalf("case-different names must not be duplicates: %v", err)
160		}
161		// Spacing differences are different names (no trimming).
162		valid = `{` + base + `,"clusters":[{"id":"x","tags":{" env":"prod","env":"dev"}}]}`
163		if _, err := ParseReleaseInput([]byte(valid)); err != nil {
164			t.Fatalf("spacing-different names must not be duplicates: %v", err)
165		}
166	}
167	
168	func TestParse_DuplicateCheckIsPerObject(t *testing.T) {
169		base := `"app":"a","revision":"r","image":"i","batchSize":1`
170		// Two clusters may both have an "env" tag.
171		valid := `{` + base + `,"clusters":[` +
172			`{"id":"a","tags":{"env":"prod"}},` +
173			`{"id":"b","tags":{"env":"dev"}}]}`
174		if _, err := ParseReleaseInput([]byte(valid)); err != nil {
175			t.Fatalf("two clusters sharing a tag key must be valid: %v", err)
176		}
177		// Two conditions may both contain "region".
178		valid = `{` + base + `,"clusters":[],` +
179			`"include":[{"region":"us"},{"region":"eu"}]}`
180		if _, err := ParseReleaseInput([]byte(valid)); err != nil {
181			t.Fatalf("two conditions sharing a key must be valid: %v", err)
182		}
183		// Repeated identical conditions are not duplicates.
184		valid = `{` + base + `,"clusters":[],` +
185			`"include":[{"env":"prod"},{"env":"prod"}]}`
186		if _, err := ParseReleaseInput([]byte(valid)); err != nil {
187			t.Fatalf("repeated identical conditions must be valid: %v", err)
188		}
189		// Same key in parent object and nested object is fine.
190		valid = `{` + base + `,"clusters":[],"meta":{"env":"x","nested":{"env":"y"}}}`
191		if _, err := ParseReleaseInput([]byte(valid)); err != nil {
192			t.Fatalf("same key in parent and nested object must be valid: %v", err)
193		}
194	}
195	
196	func TestParse_FirstDuplicateInFileOrderWins(t *testing.T) {
197		base := `"app":"a","revision":"r","image":"i","batchSize":1`
198		// Cluster 1 has a duplicate disabled, cluster 0 has a duplicate id:
199		// cluster 0's duplicate appears earlier in the file.
200		doc := `{` + base + `,"clusters":[` +
201			`{"id":"a","id":"b"},` +
202			`{"id":"c","disabled":true,"disabled":false}]}`
203		err := parseDupErr(t, doc)
204		msg := err.Error()
205		if !strings.Contains(msg, `"id"`) || !strings.Contains(msg, "$.clusters[0]") {
206			t.Fatalf("expected clusters[0] id duplicate first, got %q", msg)
207		}
208	
209		// Duplicate inside tags of cluster 0 appears before duplicate disabled
210		// of cluster 1.
211		doc = `{` + base + `,"clusters":[` +
212			`{"id":"a","tags":{"env":1,"env":2}},` +
213			`{"id":"c","disabled":true,"disabled":false}]}`
214		err = parseDupErr(t, doc)
215		msg = err.Error()
216		if !strings.Contains(msg, `"env"`) || !strings.Contains(msg, "$.clusters[0].tags") {
217			t.Fatalf("expected clusters[0].tags env duplicate first, got %q", msg)
218		}
219	
220		// Duplicate in an earlier include condition beats a later cluster dup.
221		doc = `{` + base + `,` +
222			`"include":[{"env":"prod","env":"dev"}],` +
223			`"clusters":[{"id":"a","disabled":true,"disabled":false}]}`
224		err = parseDupErr(t, doc)
225		msg = err.Error()
226		if !strings.Contains(msg, `"env"`) || !strings.Contains(msg, "$.include[0]") {
227			t.Fatalf("expected include[0] env duplicate first, got %q", msg)
228		}
229	}
230	
231	func TestParse_DuplicateBeatsBusinessErrors(t *testing.T) {
232		// Duplicate member plus missing app: duplicate error must come first.
233		doc := `{"revision":"r","image":"i","batchSize":1,"clusters":[` +
234			`{"id":"a","disabled":true,"disabled":false}]}`
235		err := parseDupErr(t, doc)
236		if !strings.Contains(err.Error(), "disabled") {
237			t.Fatalf("expected duplicate error before business error, got %q", err)
238		}
239	
240		// Duplicate plus empty tag key: duplicate wins.
241		doc = `{"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[` +
242			`{"id":"a","tags":{"env":1,"env":2,"":3}}]}`
243		err = parseDupErr(t, doc)
244		if !strings.Contains(err.Error(), "env") {
245			t.Fatalf("expected duplicate error before tag-key error, got %q", err)
246		}
247	
248		// With no duplicate, business errors are still reported as before.
249		doc = `{"revision":"r","image":"i","batchSize":1,"clusters":[]}`
250		if _, err := ParseReleaseInput([]byte(doc)); err == nil ||
251			!strings.Contains(err.Error(), "app") {
252			t.Fatalf("expected missing app error, got %v", err)
253		}
254	}
255	
256	func TestParse_ValidConfigsStillPlan(t *testing.T) {
257		raw := `{
258			"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
259			"batchSize": 2,
260			"clusters": [
261				{"id": "c3", "tags": {"env": "prod"}},
262				{"id": "c1", "tags": {"env": "dev"}},
263				{"id": "c2", "disabled": true, "tags": {"env": "prod"}},
264				{"id": "c4", "tags": {"env": "prod", "region": "us"}}
265			],
266			"include": [{"env": "prod"}],
267			"exclude": [{"region": "us"}]
268		}`
269		in, err := ParseReleaseInput([]byte(raw))
270		if err != nil {
271			t.Fatal(err)
272		}
273		plan, err := MakeReleasePlan(in)
274		if err != nil {
275			t.Fatal(err)
276		}
277		// c1 is dev -> include-not-matched; c2 disabled; c4 prod+us -> excluded;
278		// c3 selected.
279		if len(plan.Batches) != 1 || strings.Join(plan.Batches[0].Clusters, ",") != "c3" {
280			t.Fatalf("unexpected plan: %+v", plan.Batches)
281		}
282		if len(plan.Excluded) != 3 {
283			t.Fatalf("expected 3 excluded, got %+v", plan.Excluded)
284		}
285	}
286	
287	// runCLI invokes the darksafe command with the given arguments and returns
288	// exit code, stdout and stderr.
289	func runCLI(t *testing.T, args ...string) (int, string, string) {
290		t.Helper()
291		cmd := exec.Command("go", append([]string{"run", "./cmd/darksafe"}, args...)...)
292		cmd.Dir = ".."
293		var stdout, stderr strings.Builder
294		cmd.Stdout = &stdout
295		cmd.Stderr = &stderr
296		err := cmd.Run()
297		code := 0
298		if err != nil {
299			if exitErr, ok := err.(*exec.ExitError); ok {
300				code = exitErr.ExitCode()
301			} else {
302				t.Fatalf("failed to run command: %v", err)
303			}
304		}
305		return code, stdout.String(), stderr.String()
306	}
