	}
}

func TestPlan_SpreadByExcludedClustersNeedNoTag(t *testing.T) {
	in := parsePlan(t, `{
		"app": "app", "revision": "r1", "image": "img", "batchSize": 2,
		"spreadBy": "zone",
		"clusters": [
			{"id": "a", "tags": {"zone": "east"}},
