		],
		"include": [{"env": "prod"}, {"zone": "east"}, {"zone": "west"}]
	}`)
	plan, err := MakeReleasePlan(in)
	if err != nil {
		t.Fatal(err)
	}
	want := []string{"a,b"}
	if got := batchIDs(plan); strings.Join(got, "|") != strings.Join(want, "|") {
